// Data dari simulator ESP32
const data = msg.payload;
data.received = new Date().toISOString();
flow.set('lastSensor', data);               // dipakai GET /api/suhu

// Cek batas suhu (Tugas 1)
const th = flow.get('threshold') || { max: 30 };
const over = data.suhu > th.max;
const wasOver = flow.get('alertActive') || false;
flow.set('alertActive', over);

// Output 1 -> SQLite (Tugas 5)
const dbMsg = { params: {
  $suhu: data.suhu,
  $kelembaban: data.kelembaban,
  $ts: data.timestamp,
  $received: data.received
}};

// Output 2 -> WebSocket realtime (Tugas 4)
const wsMsg = { payload: { type: 'sensor', data: data, threshold: th, over: over } };

// Output 3 -> notifikasi, HANYA saat suhu baru melewati batas
let alertMsg = null;
if (over && !wasOver) {
  alertMsg = {
    topic: 'iot/alert',
    payload: {
      type: 'alert',
      message: 'Suhu ' + data.suhu + '°C melewati batas ' + th.max + '°C',
      suhu: data.suhu, batas: th.max, time: data.received
    }
  };
}
return [dbMsg, wsMsg, alertMsg];

